def is_samepatterns(words, pattern):
    """
    Return True if `words` follows the same pattern as `pattern`.

    Equal elements in `pattern` must correspond to equal elements in `words`,
    and distinct elements in `pattern` must correspond to distinct elements in `words`.
    """
    if len(words) != len(pattern):
        return False

    word_to_pattern = {}
    pattern_to_word = {}

    for word, pat in zip(words, pattern):
        if pat in pattern_to_word:
            if pattern_to_word[pat] != word:
                return False
        else:
            if word in word_to_pattern:
                return False
            pattern_to_word[pat] = word
            word_to_pattern[word] = pat

    return True


