class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        n, m = len(s), len(t)

        s_substrings = {s[i:j] for i in range(n + 1) for j in range(i, n + 1)}
        t_substrings = {t[i:j] for i in range(m + 1) for j in range(i, m + 1)}

        s_options = sorted(
            ((part, len(part)) for part in s_substrings),
            key=lambda x: x[1],
            reverse=True
        )
        t_options = sorted(
            ((part, len(part)) for part in t_substrings),
            key=lambda x: x[1],
            reverse=True
        )

        ans = 0
        max_possible = n + m

        for left, left_len in s_options:
            if left_len + m <= ans:
                break

            for right, right_len in t_options:
                total_len = left_len + right_len
                if total_len <= ans:
                    break

                candidate = left + right
                if candidate == candidate[::-1]:
                    ans = total_len
                    if ans == max_possible:
                        return ans

        return ans
