    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        max_group = max(groups)
        inf = len(elements)

        # first_index[v] = smallest index j such that elements[j] == v
        first_index = [inf] * (max_group + 1)
        for j, value in enumerate(elements):
            if value <= max_group and first_index[value] == inf:
                first_index[value] = j

        # best[g] = smallest element index that can be assigned to a group of size g
        best = [inf] * (max_group + 1)

        for divisor in range(1, max_group + 1):
            candidate_index = first_index[divisor]
            if candidate_index == inf:
                continue

            for multiple in range(divisor, max_group + 1, divisor):
                if best[multiple] > candidate_index:
                    best[multiple] = candidate_index

        return [best[g] if best[g] != inf else -1 for g in groups]
